begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
update public.community_operations set enabled=true,enrollment=true,discovery=true,publish=true,engagement=true,cohort_required=false;
create function pg_temp.group_fixture_receipt() returns trigger language plpgsql as $$begin new.terms_version:='2026-09-30';new.terms_accepted_at:=now();new.adult_declared_at:=now();return new;end $$;
create trigger community_group_fixture_receipt before insert on public.community_profiles for each row execute function pg_temp.group_fixture_receipt();
insert into auth.users(id,email) select ('c1570000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'comm157-'||i||'@mizyun.test' from generate_series(1,4)i;
update public.profiles set birth_year=extract(year from now())::integer-30 where id::text like 'c1570000%';
insert into public.community_profiles(user_id,handle,display_name,status) select id,'comm157_'||right(id::text,12),'Synthetic member','active' from auth.users where id::text like 'c1570000%';
insert into public.community_relationships(follower_user_id,target_user_id,status) values
 ('c1570000-0000-4000-8000-000000000001','c1570000-0000-4000-8000-000000000002','approved'),
 ('c1570000-0000-4000-8000-000000000001','c1570000-0000-4000-8000-000000000003','approved');
insert into public.community_moderation_staff(user_id,active) values('c1570000-0000-4000-8000-000000000001',true),('c1570000-0000-4000-8000-000000000004',true);
create temp table group_state(key text primary key,value jsonb);
grant all on group_state to authenticated;
-- Fixture supplies versions a legitimate current UI would have read; production RPC still authorizes every action.
create function pg_temp.group_args(p_target uuid default null) returns jsonb language sql security definer set search_path='' as $$
 select jsonb_build_object('groupId',s.value->'group'->>'id','membershipVersion',m.version,'targetUserId',p_target,'targetMembershipVersion',t.version)
 from pg_temp.group_state s left join public.community_group_members m on m.group_id=(s.value->'group'->>'id')::uuid and m.user_id=auth.uid()
 left join public.community_group_members t on t.group_id=m.group_id and t.user_id=p_target where s.key='group'
$$;
set local role authenticated;
set local request.jwt.claim.role='authenticated';
set local request.jwt.claim.sub='c1570000-0000-4000-8000-000000000001';
select throws_ok($$select public.community_groups_rpc('create','{"name":"Friends","rules":"Be kind","operationId":"e1570000-0000-4000-8000-000000000001"}')$$,'P0001','community_unavailable','Groups default disabled, no implicit rollout');
reset role;
update public.community_feature_controls set enabled=true where feature='groups';
set local role authenticated;
insert into group_state values('group',public.community_groups_rpc('create','{"name":"Friends","rules":"Be kind","operationId":"e1570000-0000-4000-8000-000000000001"}'));
select is(public.community_groups_rpc('create','{"name":"Friends","rules":"Be kind","operationId":"e1570000-0000-4000-8000-000000000001"}')->'group'->>'id',(select value->'group'->>'id' from group_state where key='group'),'Lost create response returns exact existing group');
select throws_ok($$select public.community_groups_rpc('create','{"name":"Changed","rules":"Be kind","operationId":"e1570000-0000-4000-8000-000000000001"}')$$,'P0001','community_conflict','Replay cannot silently change group');
select throws_ok($$select * from public.community_groups$$,'42501',null,'Raw groups cannot disclose invitation codes');
select throws_ok($$select * from public.community_group_operations$$,'42501',null,'Private operation ledger requires caller-owned export');
select throws_ok($$update public.community_group_members set role='owner'$$,'42501',null,'Direct role escalation denied');
select throws_ok($$select public.community_group_cleanup_user('c1570000-0000-4000-8000-000000000002')$$,'42501',null,'Internal lifecycle cleanup cannot be called by member');
select throws_ok($$select public.community_groups_rpc('invite',pg_temp.group_args('c1570000-0000-4000-8000-000000000004'))$$,'P0001','community_unavailable','Unrelated stranger cannot be targeted with invitation');
select lives_ok($$select public.community_groups_rpc('post',pg_temp.group_args()||'{"operationId":"e1570000-0000-4000-8000-000000000002","body":"Before membership","acceptedAudience":true}')$$,'Separate text audience publishes only explicit text');
select lives_ok($$select public.community_groups_rpc('invite',pg_temp.group_args('c1570000-0000-4000-8000-000000000002'))$$,'Approved friend can be invited');
set local request.jwt.claim.sub='c1570000-0000-4000-8000-000000000002';
select is(public.community_groups_rpc('list','{}')->'groups'->0->>'state','invited','Invitation never auto-joins');
select is(public.community_groups_rpc('list','{}')->'groups'->0->>'name','Private group','Pending invitation cannot expose group name or rules');
select throws_ok($$select public.community_groups_rpc('read',pg_temp.group_args())$$,'P0001','community_access_denied','Invite alone gives no content or member history');
select throws_ok($$select public.community_groups_rpc('join',pg_temp.group_args()||'{"membershipVersion":999}')$$,'P0001','community_conflict','Stale invitation cannot be accepted');
select lives_ok($$select public.community_groups_rpc('join',pg_temp.group_args())$$,'Recipient explicitly joins current invitation');
reset role;
-- now() is transaction-stable, so fixture separates pre-join history from join timestamp.
update public.community_group_posts set created_at=now()-interval '1 minute' where operation_id='e1570000-0000-4000-8000-000000000002';
set local role authenticated;
select is(jsonb_array_length(public.community_groups_rpc('read',pg_temp.group_args())->'posts'),0,'New member cannot backfill earlier group posts');
select throws_ok($$select public.community_groups_rpc('code',pg_temp.group_args())$$,'P0001','community_access_denied','Regular member cannot invite or rotate codes');
select throws_ok($$select public.community_groups_rpc('post',pg_temp.group_args()||'{"operationId":"e1570000-0000-4000-8000-000000000003","body":"Hello","acceptedAudience":false}')$$,'P0001','community_invalid_action','Publication confirmation enforced at direct SQL boundary');
select lives_ok($$select public.community_groups_rpc('post',pg_temp.group_args()||'{"operationId":"e1570000-0000-4000-8000-000000000003","body":"Hello","acceptedAudience":true}')$$,'Member explicitly posts');
select lives_ok($$select public.community_groups_rpc('post',pg_temp.group_args()||'{"operationId":"e1570000-0000-4000-8000-000000000003","body":"Hello","acceptedAudience":true}')$$,'Lost post response retry creates no duplicate');
reset role;
select is((select count(*) from public.community_group_posts where operation_id='e1570000-0000-4000-8000-000000000003'),1::bigint,'Exactly one post across response retry');
set local role authenticated;
insert into group_state values('post',jsonb_build_object('id',(select id from public.community_group_posts where operation_id='e1570000-0000-4000-8000-000000000003')));
set local request.jwt.claim.sub='c1570000-0000-4000-8000-000000000004';
select is((select count(*) from public.community_group_posts),0::bigint,'RLS hides even guessed private-group posts from unrelated account');
select ok(not public.community_group_post_visible((select (value->>'id')::uuid from group_state where key='post'),'c1570000-0000-4000-8000-000000000002'),'Visibility RPC cannot oracle another principal');
select throws_ok($$select public.community_groups_rpc('read',pg_temp.group_args())$$,'P0001','community_access_denied','Group UUID does not confer access');
set local request.jwt.claim.sub='c1570000-0000-4000-8000-000000000001';
select throws_ok($$select public.community_groups_rpc('leave',pg_temp.group_args())$$,'P0001','community_conflict','Last-owner prevention requires transfer before leaving others');
select lives_ok($$select public.community_groups_rpc('role',pg_temp.group_args('c1570000-0000-4000-8000-000000000002')||'{"role":"moderator"}')$$,'Owner explicitly promotes moderator');
insert into group_state values('code',public.community_groups_rpc('code',pg_temp.group_args()));
set local request.jwt.claim.sub='c1570000-0000-4000-8000-000000000003';
insert into group_state values('request',public.community_groups_rpc('request',jsonb_build_object('token',(select value->>'inviteCode' from group_state where key='code'))));
select is(public.community_groups_rpc('list','{}')->'groups'->0->>'state','pending','Possessing private code requests membership only');
set local request.jwt.claim.sub='c1570000-0000-4000-8000-000000000002';
select throws_ok($$select public.community_groups_rpc('role',pg_temp.group_args('c1570000-0000-4000-8000-000000000003')||'{"role":"moderator"}')$$,'P0001','community_access_denied','Moderator cannot escalate another role');
select lives_ok($$select public.community_groups_rpc('approve',pg_temp.group_args('c1570000-0000-4000-8000-000000000003'))$$,'Moderator approves a current request');
select lives_ok($$select public.community_groups_rpc('ban',pg_temp.group_args('c1570000-0000-4000-8000-000000000003')||'{"reason":"Repeated unsafe advice"}')$$,'Moderator can ban regular member with reason');
set local request.jwt.claim.sub='c1570000-0000-4000-8000-000000000003';
select throws_ok($$select public.community_groups_rpc('read',pg_temp.group_args())$$,'P0001','community_access_denied','Banned membership immediately loses history');
select lives_ok($$select public.community_groups_rpc('leave',pg_temp.group_args())$$,'Banned account can remove own group posts without lifting ban');
select throws_ok($$select public.community_groups_rpc('request',jsonb_build_object('token',(select value->>'inviteCode' from group_state where key='code')))$$,'P0001','community_access_denied','Leave/rejoin cannot bypass a ban');
select lives_ok($$select public.community_groups_rpc('appeal',pg_temp.group_args()||'{"reason":"Please review the moderator action"}')$$,'Banned member can appeal');
select lives_ok($$select * from public.community_submit_report('group',(select value->'group'->>'id' from group_state where key='group'),'harassment','Moderator abuse')$$,'Captured group receipt permits report after ban');
set local request.jwt.claim.sub='c1570000-0000-4000-8000-000000000001';
select lives_ok($$select public.community_groups_rpc('resolveAppeal',pg_temp.group_args()||jsonb_build_object('appealId',(public.community_groups_rpc('read',pg_temp.group_args())->'appeals'->0->>'id'),'appealMembershipVersion',(public.community_groups_rpc('read',pg_temp.group_args())->'appeals'->0->>'membershipVersion')::integer,'decision','approved','reason','Independent owner review accepted'))$$,'Independent owner reviews moderator ban');
set local request.jwt.claim.sub='c1570000-0000-4000-8000-000000000003';
select is(public.community_groups_rpc('list','{}')->'groups'->0->>'state','removed','Approved appeal does not auto-join or expose history');
select lives_ok($$select public.community_groups_rpc('request',jsonb_build_object('token',(select value->>'inviteCode' from group_state where key='code')))$$,'Fresh request required after appeal approval');
set local request.jwt.claim.sub='c1570000-0000-4000-8000-000000000001';
select lives_ok($$select public.community_groups_rpc('approve',pg_temp.group_args('c1570000-0000-4000-8000-000000000003'))$$,'Owner approves fresh membership');
insert into group_state values('oldTarget',pg_temp.group_args('c1570000-0000-4000-8000-000000000003'));
select lives_ok($$select public.community_groups_rpc('role',pg_temp.group_args('c1570000-0000-4000-8000-000000000003')||'{"role":"moderator"}')$$,'Target incarnation changes with promotion');
select throws_ok($$select public.community_groups_rpc('remove',(select value from group_state where key='oldTarget'))$$,'P0001','community_conflict','Stale removal cannot alter later target incarnation');
-- An owner-issued ban has an independent named global-staff route, with mandatory MFA and audit.
select lives_ok($$select public.community_groups_rpc('ban',pg_temp.group_args('c1570000-0000-4000-8000-000000000003')||'{"reason":"Owner issued contested ban"}')$$,'Owner can issue reasoned ban');
set local request.jwt.claim.sub='c1570000-0000-4000-8000-000000000003';
select lives_ok($$select public.community_groups_rpc('appeal',pg_temp.group_args()||'{"reason":"Please independently review owner ban"}')$$,'A later ban has a distinct fresh appeal');
insert into group_state values('ownerBanAppeal',public.community_groups_rpc('list','{}')->'appeals'->0);
select throws_ok($$select public.community_groups_rpc('staffAppeals','{"reason":"Review","limit":20}')$$,'P0001','community_access_denied','Unregistered caller cannot inspect private group appeals');
set local request.jwt.claim.sub='c1570000-0000-4000-8000-000000000001';
select throws_ok($$select public.community_groups_rpc('staffResolveAppeal',(select jsonb_build_object('appealId',value->>'id','appealMembershipVersion',(value->>'membershipVersion')::integer,'decision','approved','reason','Review') from group_state where key='ownerBanAppeal'))$$,'P0001','community_access_denied','Named staff without AAL2 cannot decide');
set local request.jwt.claims='{"aal":"aal2"}';
select throws_ok($$select public.community_groups_rpc('staffResolveAppeal',(select jsonb_build_object('appealId',value->>'id','appealMembershipVersion',(value->>'membershipVersion')::integer,'decision','approved','reason','Review') from group_state where key='ownerBanAppeal'))$$,'P0001','community_access_denied','Issuing owner/staff cannot resolve their own action');
set local request.jwt.claim.sub='c1570000-0000-4000-8000-000000000004';
select is(jsonb_array_length(public.community_groups_rpc('staffAppeals','{"reason":"Independent owner ban review","limit":20}')->'appeals'),1,'Independent AAL2 staff inspects bounded queue');
reset role;
create function pg_temp.fail_group_appeal_audit() returns trigger language plpgsql as $$begin raise exception 'synthetic_group_audit_failure';end $$;
create trigger community_group_fixture_audit before insert on public.community_moderation_actions for each row execute function pg_temp.fail_group_appeal_audit();
set local role authenticated;
select throws_ok($$select public.community_groups_rpc('staffResolveAppeal',(select jsonb_build_object('appealId',value->>'id','appealMembershipVersion',(value->>'membershipVersion')::integer,'decision','approved','reason','Independent review') from group_state where key='ownerBanAppeal'))$$,'P0001','synthetic_group_audit_failure','Failed audit rolls back independent appeal decision');
reset role;
drop trigger community_group_fixture_audit on public.community_moderation_actions;
select is((select state from public.community_group_members where user_id='c1570000-0000-4000-8000-000000000003'),'banned','Audit failure does not lift membership ban');
set local role authenticated;
select lives_ok($$select public.community_groups_rpc('staffResolveAppeal',(select jsonb_build_object('appealId',value->>'id','appealMembershipVersion',(value->>'membershipVersion')::integer,'decision','approved','reason','Independent review accepted') from group_state where key='ownerBanAppeal'))$$,'Independent AAL2 staff may resolve owner-issued ban');
set local request.jwt.claim.sub='c1570000-0000-4000-8000-000000000003';
select is(public.community_groups_rpc('list','{}')->'groups'->0->>'state','removed','Global appeal reversal never automatically restores membership');
select lives_ok($$select public.community_groups_rpc('request',jsonb_build_object('token',(select value->>'inviteCode' from group_state where key='code')))$$,'Staff reversal still requires fresh request');
set local request.jwt.claims='{}';
set local request.jwt.claim.sub='c1570000-0000-4000-8000-000000000001';
select lives_ok($$select public.community_groups_rpc('approve',pg_temp.group_args('c1570000-0000-4000-8000-000000000003'))$$,'Current owner explicitly approves fresh request after staff reversal');
select lives_ok($$select public.community_groups_rpc('transfer',pg_temp.group_args('c1570000-0000-4000-8000-000000000002'))$$,'Ownership transfer is explicit');
select lives_ok($$select public.community_groups_rpc('leave',pg_temp.group_args())$$,'Former owner may leave after transfer');
reset role;
-- Bilateral block cuts off group access when the current owner is involved.
insert into public.community_blocks(blocker_user_id,blocked_user_id) values('c1570000-0000-4000-8000-000000000003','c1570000-0000-4000-8000-000000000002');
set local role authenticated;
set local request.jwt.claim.sub='c1570000-0000-4000-8000-000000000003';
select throws_ok($$select public.community_groups_rpc('read',pg_temp.group_args())$$,'P0001','community_access_denied','Either-direction owner block revokes group content');
select is((select count(*) from public.community_group_posts),0::bigint,'Block also applies to direct post RLS');
reset role;
delete from public.community_blocks where blocker_user_id='c1570000-0000-4000-8000-000000000003';
update public.community_feature_controls set enabled=false where feature='groups';
set local role authenticated;
select is(public.community_groups_rpc('list','{}')->'groups'->0->>'name','Private group','Frozen feature lists only own generic privacy controls');
select lives_ok($$select public.community_groups_rpc('leave',pg_temp.group_args())$$,'Privacy leave survives feature switch off');
set local request.jwt.claim.sub='c1570000-0000-4000-8000-000000000002';
select lives_ok($$select public.community_groups_rpc('deletePost',pg_temp.group_args()||jsonb_build_object('postId',(select item->>'id' from public.community_export_page('groupPosts',null,500) limit 1)))$$,'Own post privacy removal survives feature switch off');
select is((select count(*) from public.community_export_page('groupMemberships',null,500)),1::bigint,'Group export includes only own membership');
reset role;
delete from public.community_group_posts where operation_id='e1570000-0000-4000-8000-000000000003';
update public.community_feature_controls set enabled=true where feature='groups';
set local role authenticated;
select throws_ok($$select public.community_groups_rpc('post',pg_temp.group_args()||'{"operationId":"e1570000-0000-4000-8000-000000000003","body":"Hello","acceptedAudience":true}')$$,'P0001','community_conflict','Minimal tombstone prevents replay after actual post purge');
reset role;
-- Rejoin a remaining recovery candidate with flag enabled, then delete current owner.
update public.community_feature_controls set enabled=true where feature='groups';
set local role authenticated;
select throws_ok($$select public.community_groups_rpc('invite',pg_temp.group_args('c1570000-0000-4000-8000-000000000003'))$$,'P0001','community_unavailable','Transferred owner must still follow invitee');
update group_state set value=public.community_groups_rpc('code',pg_temp.group_args()) where key='code';
set local request.jwt.claim.sub='c1570000-0000-4000-8000-000000000003';
select lives_ok($$select public.community_groups_rpc('request',jsonb_build_object('token',(select value->>'inviteCode' from group_state where key='code')))$$,'Removed member explicitly makes fresh request');
set local request.jwt.claim.sub='c1570000-0000-4000-8000-000000000002';
select lives_ok($$select public.community_groups_rpc('approve',pg_temp.group_args('c1570000-0000-4000-8000-000000000003'))$$,'Current owner approves recovery candidate');
select lives_ok($$select public.community_groups_rpc('role',pg_temp.group_args('c1570000-0000-4000-8000-000000000003')||'{"role":"moderator"}')$$,'Current owner designates eligible moderator');
reset role;
delete from auth.users where id='c1570000-0000-4000-8000-000000000002';
select is((select user_id::text from public.community_groups where id=(select (value->'group'->>'id')::uuid from group_state where key='group')),'c1570000-0000-4000-8000-000000000003','Owner deletion recovers group to eligible current moderator');
select is((select count(*) from public.community_group_posts where user_id='c1570000-0000-4000-8000-000000000002'),0::bigint,'Deleted owner leaves no authored group content');
insert into public.community_group_operations(user_id,operation_id,kind,group_id,payload_digest,membership_version)
select 'c1570000-0000-4000-8000-000000000003',('e1570000-0000-4000-8000-'||lpad((100+i)::text,12,'0'))::uuid,'post',(select (value->'group'->>'id')::uuid from group_state where key='group'),'fixture-digest',1 from generate_series(1,20)i;
set local role authenticated;
set local request.jwt.claim.sub='c1570000-0000-4000-8000-000000000003';
select throws_ok($$select public.community_groups_rpc('post',pg_temp.group_args()||'{"operationId":"e1570000-0000-4000-8000-000000000099","body":"Over quota","acceptedAudience":true}')$$,'P0001','community_rate_limited','Daily publication cap counts operations even after content purge');
reset role;
update public.community_profiles set status='withdrawn' where user_id='c1570000-0000-4000-8000-000000000003';
select is((select count(*) from public.community_groups),0::bigint,'Sole remaining owner withdrawal disbands orphan group');
select is((select count(*) from public.community_group_appeals),0::bigint,'Disband cascades group appeals');
set local role authenticated;
set local request.jwt.claim.sub='c1570000-0000-4000-8000-000000000001';
select throws_ok($$select public.community_groups_rpc('create','{"name":"Friends","rules":"Be kind","operationId":"e1570000-0000-4000-8000-000000000001"}')$$,'P0001','community_conflict','Disbanded group never resurrects after old create response');
reset role;
select * from finish();
rollback;
